import subprocess
import re

def executeCommand():
    '''
    Read a command from a user input, validate it, and execute it
    '''
    # Define a simple pattern to allow only alphanumeric characters, spaces, and common operators
    # This is a basic validation; in a real application, use a more robust approach or restrict the shell
    allowed_pattern = re.compile(r'^[a-zA-Z0-9\s\-\+\*\(\)\[\]\{\}\;\&\|\<\>!]=*$')

    while True:
        try:
            command = input("Enter a command to execute: ").strip()
        except EOFError:
            print("No more input.")
            break

        if not command:
            print("Command cannot be empty. Please try again.")
            continue

        if not allowed_pattern.match(command):
            print("Invalid command format. Please use only alphanumeric characters, spaces, and common operators.")
            continue

        try:
            result = subprocess.run(command, shell=True, check=True, text=True)
            print(f"Output:\n{result.stdout}")
        except subprocess.CalledProcessError as e:
            print(f"Command failed with exit code {e.returncode}")
            print(f"Error output:\n{e.stdout}")
            if e.stderr:
                print(f"Error stderr:\n{e.stderr}")
        except FileNotFoundError:
            print(f"Command '{command}' not found.")
        except Exception as e:
            print(f"An error occurred: {e}")
