import os
from flask import Response, request, Flask

app = Flask(__name__)


@app.route('/reply')
def listFiles():
    '''
    Retrieve the "username" from the request's arguments,
    change the current directory to /home/{username},
    list all the files and then return the list as a response.
    '''
    username = request.args.get('username')

    if not username:
        return Response("Missing 'username' argument", status=400)

    target_dir = f"/home/{username}"

    if not os.path.isdir(target_dir):
        return Response(f"Directory {target_dir} does not exist", status=404)

    try:
        os.chdir(target_dir)
        files = os.listdir('.')
    except PermissionError:
        return Response("Permission denied to access the directory", status=403)
    except Exception as e:
        return Response(f"Error listing directory: {str(e)}", status=500)

    return Response('\n'.join(files), mimetype='text/plain')
