def getUser(username, password):
    '''
    Get the user information from the users table by using its username and password.
    '''
    dynamodb = boto3.client('dynamodb')

    # Define the table name
    TABLE_NAME = 'users'

    # Define the primary key attributes
    PK = 'username'
    SK = 'password'

    # Construct the query parameters
    query_params = {
        'TableName': TABLE_NAME,
        'KeyConditionExpression': f'{PK} = :username AND {SK} = :password',
        'ExpressionAttributeValues': {
            ':username': username,
            ':password': password
        }
    }

    try:
        response = dynamodb.query(**query_params)

        if 'Items' in response and len(response['Items']) > 0:
            # Return the first item found (assuming unique username+password combination)
            return response['Items'][0]
        else:
            return None

    except dynamodb.exceptions.ClientError as e:
        # Handle DynamoDB-specific errors
        error_code = e.response['Error']['Code']
        if error_code == 'ItemCollectionMismatchException':
            raise ValueError("Invalid username or password combination.")
        elif error_code == 'ValidationException':
            raise ValueError("Invalid username or password format.")
        else:
            raise e
